update pm_task
set status = #{status}, update_time = CURRENT_TIMESTAMP
where project_id = #{projectId}
  and task_id = #{taskId}
  and is_deleted = 0

update pm_task
set is_deleted = 1, update_time = CURRENT_TIMESTAMP
where project_id = #{projectId}
  and task_id = #{taskId}
  and is_deleted = 0

update pm_task
set current_version_id = #{versionId}, update_time = CURRENT_TIMESTAMP
where task_id = #{taskId}

